import matplotlib.pyplot as pltfrom sys import stdoutfrom models import henonfrom mpmath import mpimport osimport csvmp.dps = 24####  Фазовый портрет динамической системы###a = mp.mpf('1.43')b = mp.mpf('0.5')c = mp.mpf('-1.7594137')x = [mp.mpf('0.1'), mp.mpf('0.1'), mp.mpf('0.1')]# Списки для данных (храним как mpmath, конвертируем при записи)fase_port_0 = []  # полный портретfase_port_1 = []  # увеличение 1fase_port_2 = []  # увеличение 2# Переходный процессprint("Переходный процесс...")for i in range(1_000_000):    x = henon(x, a, b, c)# Основной циклn = M = k = 0while k != 100:    stdout.write("\r%d" % k)    stdout.flush()    x = henon(x, a, b, c)    # Полный портрет    fase_port_0.append((x[0], x[1], x[2]))    n += 1    if (-0.38 < x[0] < -0.36) and (-0.414 < x[1] < -0.405):        fase_port_1.append((x[0], x[1], x[2]))        M += 1    if (-0.381 < x[0] < -0.378) and (-0.4088 < x[1] < -0.408):        fase_port_2.append((x[0], x[1], x[2]))        k += 1print('\n', n, M, k, sep='\n')# --- СОХРАНЕНИЕ В CSV ---output_dir = 'Portraits'os.makedirs(output_dir, exist_ok=True)print(f"📁 Данные будут сохранены в: {os.path.abspath(output_dir)}")def save_to_csv(data, filepath, params=None):    """    Сохраняет список кортежей (x, y, z) в CSV.    params — словарь с параметрами системы (запишется в шапку как комментарий).    """    with open(filepath, 'w', newline='') as f:        # Пишем параметры как комментарии (начинаются с #)        if params:            for key, val in params.items():                f.write(f"# {key} = {val}\n")        # Заголовок        f.write("x,y,z\n")        # Данные        writer = csv.writer(f)        for xi, yi, zi in data:            writer.writerow([float(xi), float(yi), float(zi)])params = {'a': a, 'b': b, 'c': c, 'mp.dps': mp.dps}save_to_csv(fase_port_0, os.path.join(output_dir, 'phase_full.csv'), params)print(f"✅ Сохранён: phase_full.csv ({len(fase_port_0)} точек)")save_to_csv(fase_port_1, os.path.join(output_dir, 'phase_zoom1.csv'), params)print(f"✅ Сохранён: phase_zoom1.csv ({len(fase_port_1)} точек)")save_to_csv(fase_port_2, os.path.join(output_dir, 'phase_zoom2.csv'), params)print(f"✅ Сохранён: phase_zoom2.csv ({len(fase_port_2)} точек)")print(f"\n🎉 Все CSV сохранены в: {os.path.abspath(output_dir)}")